/// Read `cx:series` into a `Series`.
#[must_use]
pub fn series(element: &Element) -> super::Series {
    let mut node = super::Series::default();
    let mut reader = markup::Reader::new(element, &super::SERIES_SHAPE);
    for (index, field) in &mut reader {
        match index {
            0 => field.attribute(&mut node.layout_id),
            1 => field.attribute(&mut node.hidden),
            2 => field.attribute(&mut node.owner_idx),
            3 => field.attribute(&mut node.unique_id),
            4 => field.attribute(&mut node.format_idx),
            5 => field.child(&mut node.tx),
            6 => field.child(&mut node.sp_pr),
            7 => field.child(&mut node.value_colors),
            8 => field.child(&mut node.value_color_positions),
            9 => field.child(&mut node.data_pt),
            10 => field.child(&mut node.data_labels),
            11 => field.child(&mut node.data_id),
            12 => field.child(&mut node.layout_pr),
            13 => field.child(&mut node.axis_id),
            14 => field.child(&mut node.ext_lst),
            _ => {}
        }
    }
    node.unknown = reader.finish();
    node
}

